payload.input:
const q=s=>"'"+s.replace(/'/g,"'\\''")+"'";
const checks=load("larkspur_protected_hashes");
const verify = "import hashlib,json,pathlib,sys\nbaseline=json.loads(sys.argv[1])\nchanged=[p for p,digest in baseline.items() if not pathlib.Path(p).is_file() or hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()!=digest]\nprint(json.dumps({'protected_files_checked':len(baseline),'changed_or_missing':changed}))\nsys.exit(bool(changed))";
const actual = `import hashlib,json,pathlib,sys
sys.path.insert(0,'skills/class-code-assistant')
from employer_processing import process_employer
root=pathlib.Path('/home/maxg/insurance01-inputs')
r=process_employer(root/'classification-guide.md',root/'employer-files/larkspur-lane-bistro','interviews/ch03-premium-audit-20261105-0222(1).md')
for decision in r.decisions.values():
 for ref in decision.rule_sources+decision.evidence_sources:
  raw=pathlib.Path(ref.source).read_bytes()
  assert hashlib.sha256(raw).hexdigest()==ref.sha256
  assert ref.excerpt in '\\n'.join(raw.decode().splitlines()[ref.line_start-1:ref.line_end])
assert r.independent_reconciliation.reconciled
print(json.dumps({'verified_by_code':r.by_code,'unresolved':r.allocation.reconciliation.unresolved_total,'register':r.independent_reconciliation.register_total,'difference':r.independent_reconciliation.difference,'catering_decision_reasons':{key:value.reason for key,value in r.decisions.items() if value.status=='OPEN'},'open_questions':[item.subject for item in r.open_items],'source_hashes_and_line_spans':'verified'},default=str,indent=2))
`;
const results=await Promise.allSettled([
tools.exec_command({cmd:"python3 -B -c "+q(verify)+" "+q(JSON.stringify(checks)),"max_output_tokens":1500}),
tools.exec_command({cmd:"python3 -B -c "+q(actual),"max_output_tokens":2200}),
tools.exec_command({cmd:"git diff --exit-code","max_output_tokens":1000}),
tools.exec_command({cmd:"git diff --cached --exit-code","max_output_tokens":1000}),
tools.exec_command({cmd:"nl -ba /home/maxg/insurance01-inputs/classification-guide.md","max_output_tokens":3500})
]);results.forEach(text);

